const t=JSON.parse('{"key":"v-418b3708","path":"/ACM-docs/%E6%95%B0%E5%AD%A6/%E6%95%B0%E8%AE%BA/%E7%B1%BB%E6%AC%A7%E5%87%A0%E9%87%8C%E5%BE%97%E7%AE%97%E6%B3%95.html","title":"类欧几里得算法","lang":"zh-CN","frontmatter":{"summary":"类欧几里得算法 求解： $$ f(a,b,c,n)=\\\\sum_{i=0}^n\\\\left\\\\lfloor \\\\frac{ai+b}{c}\\\\right\\\\rfloor \\\\\\\\ $$ 令 $$ m=\\\\left\\\\lfloor \\\\frac{an+b}{c}\\\\right\\\\rfloor $$ 则 $$ f(a,b,c,n)=nm- f(c,c-b-1,a,m-1) $$","head":[["meta",{"property":"og:url","content":"https://ClearDewy.github.io/ACM-docs/%E6%95%B0%E5%AD%A6/%E6%95%B0%E8%AE%BA/%E7%B1%BB%E6%AC%A7%E5%87%A0%E9%87%8C%E5%BE%97%E7%AE%97%E6%B3%95.html"}],["meta",{"property":"og:site_name","content":"Dewy-Wiki"}],["meta",{"property":"og:title","content":"类欧几里得算法"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:updated_time","content":"2022-10-22T12:47:42.000Z"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:modified_time","content":"2022-10-22T12:47:42.000Z"}]]},"excerpt":"","headers":[],"git":{"createdTime":1666442862000,"updatedTime":1666442862000,"contributors":[{"name":"Qingtuan","email":"2233408834@qq.com","commits":1}]},"readingTime":{"minutes":0.14,"words":42},"filePathRelative":"ACM-docs/数学/数论/类欧几里得算法.md","localizedDate":"2022年10月22日"}');export{t as data};
